export const dns = {
  zona: "example.com",
  comprobaciones: [
    { id: "hc-principal", endpoint: "192.0.2.10", tipoEndpoint: "ipv4" },
  ],
  registros: [
    { nombre: "www.example.com", tipo: "A", politica: "failover", rol: "primary", valor: "192.0.2.10", comprobacion: "hc-principal" },
    { nombre: "www.example.com", tipo: "A", politica: "failover", rol: "secondary", valor: "192.0.2.20", comprobacion: null },
  ],
};

spec.code:
const principal = dns.registros.find((r) => r.rol === "primary");
assert.ok(principal, "debe existir el registro principal");
const hc = dns.comprobaciones.find((c) => c.id === principal.comprobacion);
assert.ok(hc, "el registro principal debe referirse a una comprobación existente");
assert.strictEqual(hc.endpoint, principal.valor, "la comprobación debe vigilar el endpoint del principal");

const principal = dns.registros.find((r) => r.rol === "primary");
const secundario = dns.registros.find((r) => r.rol === "secondary");
assert.strictEqual(principal.valor, "192.0.2.10");
assert.strictEqual(secundario.valor, "192.0.2.20");
assert.ok(dns.registros.every((r) => r.nombre === "www.example.com" && r.tipo === "A"));

