export const dns = {
  zona: "example.com",
  politica: "multivalue",
  respuestasMaximas: 8,
  comprobaciones: [
    { id: "hc-a", endpoint: "192.0.2.31" },
    { id: "hc-b", endpoint: "192.0.2.32" },
    { id: "hc-c", endpoint: "192.0.2.33" },
  ],
  registros: [
    { nombre: "api.example.com", tipo: "A", valor: "192.0.2.31", comprobacion: "hc-a" },
    { nombre: "api.example.com", tipo: "A", valor: "192.0.2.32", comprobacion: "hc-b" },
    { nombre: "api.example.com", tipo: "A", valor: "192.0.2.33", comprobacion: "hc-c" },
  ],
};

spec.code:
for (const r of dns.registros) {
  const hc = dns.comprobaciones.find((c) => c.id === r.comprobacion);
  assert.ok(hc, r.valor + " debe tener una comprobación existente");
  assert.strictEqual(hc.endpoint, r.valor, "la comprobación debe vigilar " + r.valor);
}

const a = dns.comprobaciones.find((c) => c.id === "hc-a");
const b = dns.comprobaciones.find((c) => c.id === "hc-b");
assert.deepStrictEqual(a, { id: "hc-a", endpoint: "192.0.2.31" });
assert.deepStrictEqual(b, { id: "hc-b", endpoint: "192.0.2.32" });
assert.strictEqual(dns.registros.length, 3);
